from typing import Annotated
from fastapi import Depends, FastAPI
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from fastapi.testclient import TestClient

app = FastAPI()
security = HTTPBearer()

@app.get("/users/me")
def read_current_user(
    credentials: Annotated[HTTPAuthorizationCredentials, Depends(security)]
):
    return {"scheme": credentials.scheme, "credentials": credentials.credentials}

client = TestClient(app)

def test_auth_header():
    # Test case 1: Single space (correct)
    res1 = client.get("/users/me", headers={"Authorization": "Bearer xxx"})
    print(f"Test 1: {res1.json()}")
    assert res1.json() == {"scheme": "Bearer", "credentials": "xxx"}

    # Test case 2: Multiple spaces
    res2 = client.get("/users/me", headers={"Authorization": "Bearer   xxx"})
    print(f"Test 2: {res2.json()}")
    assert res2.json() == {"scheme": "Bearer", "credentials": "xxx"}

    # Test case 3: Trailing whitespace
    res3 = client.get("/users/me", headers={"Authorization": "Bearer xxx "})
    print(f"Test 3: {res3.json()}")
    assert res3.json() == {"scheme": "Bearer", "credentials": "xxx"}

if __name__ == "__main__":
    test_auth_header()
EOF

